; sm1.sm1 - board Z80 sound program (64 KB, the ROM holds it twice)
; generated by tools/sm1.py from sm1/names.csv and sm1/hints.txt - edit those
; assemble: z80asm (tools/sm1.py build)

; I/O ports
PORT_SOUND_CODE:	equ 000h	; [W] read: the command byte from the 68k (and acknowledges the NMI); write: clears it (NeoGeoDev wiki Z80 port map)
PORT_YM_ADDR_A:	equ 004h	; [W] YM2610 address port A
PORT_YM_DATA_A:	equ 005h	; [W] YM2610 data port A
PORT_YM_ADDR_B:	equ 006h	; [W] YM2610 address port B
PORT_YM_DATA_B:	equ 007h	; [W] YM2610 data port B
PORT_NMI_ENABLE:	equ 008h	; [W] write: enables the NMI (command from the 68k); read: bank $F000-$F7FF
PORT_REPLY:	equ 00ch	; [W] write: the reply byte the 68k reads in REG_SOUND
PORT_NMI_DISABLE:	equ 018h	; [W] write: disables the NMI
PORT_C0:	equ 0c0h	; [W] mirror of port $00 (only address bits 2-3 decoded, wiki); Init writes 1 to it

; work RAM ($F800-$FFFF)
SsgPeriodA:	equ 0f800h	; [C] start of the 2 KB RAM (cleared by Init); word: SSG period kept for channel 5 (command 5Fh reads it)
SsgPeriodB:	equ 0f802h	; [C] word: the same for channel 6
SsgPeriodC:	equ 0f804h	; [C] word: the same for channel 7
SsgSlideA:	equ 0f806h	; [I] 11-byte block of channel 5 set by command 5Fh (flag, period, step); cleared by Init
SsgSlideB:	equ 0f811h	; [I] the same for channel 6
SsgSlideC:	equ 0f81ch	; [I] the same for channel 7
LoopStacks:	equ 0f827h	; [C] loop counters and return addresses of commands 31h/32h and 34h/38h, 16 bytes per channel (base + channel x 16, sub_27DD)
CallStacks:	equ 0f957h	; [C] return addresses of commands 35h/36h (call, return), 16 bytes per channel
AdpcmBEnvelopeOn:	equ 0fa88h	; [I] ADPCM-B envelope enabled (tested when $FE2F is 0; AdpcmBEnvelopeStart, TickParamsA)
AdpcmBEnvelopeOn2:	equ 0fa89h	; [I] the same, tested when $FE2F is set
AdpcmBParams:	equ 0fa8ah	; [I] 26-byte block of the ADPCM-B envelope and pitch state ($FA8A-$FAA3), saved and restored as a whole
AdpcmBSavedParams:	equ 0faa4h	; [C] copy of AdpcmBParams (AdpcmBSaveParams / AdpcmBRestoreParams)
AdpcmAMaster:	equ 0fabeh	; [I] ADPCM-A master block (iy): +0 flags, +1 and +6/+7 from the song header (+24 to +26), YM port B $01 total level
AdpcmBState:	equ 0fac6h	; [I] ADPCM-B state block (iy) of AdpcmBLoadParams and TimerIrq
TimerAShadow:	equ 0faceh	; [C] copy of the timer A value: +4 YM $24, +5 YM $25 (command 37h)
FmShadowA:	equ 0fadeh	; [I] FM operator register copies of channels 1-2 (port A), written by the instrument loader sub_162E
FmShadowB:	equ 0fb65h	; [I] the same for channels 3-4 (port B)
AdpcmVoices:	equ 0fbech	; [I] three 9-byte voice blocks for the ADPCM-A sounds (AdpcmVoice)
AdpcmARepeatRecords:	equ 0fc07h	; [I] 7-byte repeat record per ADPCM-A channel: count, start and end addresses (AdpcmARepeat)
LfoValue1:	equ 0fc31h	; [I] set by SeqLfo, read by AdpcmBChannelNote
LfoValue2:	equ 0fc32h	; [I] set by SeqLfo, read by AdpcmBChannelNote
PitchEnvelopeOn:	equ 0fc33h	; [I] enables TickParamsB (read when $FE2F is 0); set by SeqLfo, cleared by Init
PitchEnvelopeOn2:	equ 0fc34h	; [I] the same, read when AdpcmBEffectMode is set
AdpcmBSoundOn:	equ 0fc35h	; [I] set while an ADPCM-B sound effect (type 4) plays; StartAdpcmBSound, AdpcmBTick, AdpcmBStop
AdpcmBSoundPriority:	equ 0fc36h	; [I] priority of the ADPCM-B sound effect playing
AdpcmBNoteLevel:	equ 0fc37h	; [I] level of the last ADPCM-B song note (AdpcmBChannelNote)
EnginePass2:	equ 0fc38h	; [I] set by TimerIrq around its second pass over the channels; changes the stack entries (ChannelStackEntry) and the ADPCM paths
SeqFlagFC39:	equ 0fc39h	; [?] written by one sequence command handler only
ModulationOff:	equ 0fc3ah	; [I] 4 bytes, one per FM channel 1-4: UpdateModulation runs only when it is 0
AdpcmBRepeatCount:	equ 0fc3eh	; [I] repeat count of the ADPCM-B sample ($FF forever), AdpcmBTick
AdpcmBRepeatStart:	equ 0fc3fh	; [I] word: start address of the repeated ADPCM-B sample
AdpcmBRepeatEnd:	equ 0fc41h	; [I] word: end address of the repeated ADPCM-B sample
AdpcmBLastAddress:	equ 0fc43h	; [I] word: last address for the ADPCM-B repeat (AdpcmBRestoreParams)
AdpcmALevels:	equ 0fc50h	; [C] copies of YM port B $08-$0D at +8 (AdpcmAWriteLevel)
ModulationBlocks:	equ 0fc80h	; [I] 16-byte block per channel (ModulationBlock), loaded from the instrument (LoadModulation)
AdpcmBChannel:	equ 0fcd0h	; [I] channel block of the ADPCM-B sounds (type 4)
ChannelOwner:	equ 0fcd9h	; [C] one byte per channel number (0-14): written by sub_28EC with b & 7 when a sound takes the channel
Channel1:	equ 0fce8h	; [C] 16-byte block of song channel 1 (FM): +0 flags, +9/+10 sequence pointer, +11/+12 sequence start (PlaySound)
Channel2:	equ 0fcf8h	; [C] song channel 2 (FM)
Channel3:	equ 0fd08h	; [C] song channel 3 (FM)
Channel4:	equ 0fd18h	; [C] song channel 4 (FM)
Channel8:	equ 0fd28h	; [C] song channel 8 (ADPCM-A)
Channel9:	equ 0fd38h	; [C] song channel 9 (ADPCM-A)
Channel10:	equ 0fd48h	; [C] song channel 10 (ADPCM-A)
Channel11:	equ 0fd58h	; [C] song channel 11 (ADPCM-A)
Channel12:	equ 0fd68h	; [C] song channel 12 (ADPCM-A)
Channel13:	equ 0fd78h	; [C] song channel 13 (ADPCM-A)
Channel14:	equ 0fd88h	; [C] song channel 14 (ADPCM-B)
EffectChannel5:	equ 0fd98h	; [C] effect channel 5 (SSG A), sub_0881
EffectChannel6:	equ 0fda8h	; [C] effect channel 6 (SSG B)
EffectChannel7:	equ 0fdb8h	; [C] effect channel 7 (SSG C)
EffectChannel0:	equ 0fdc8h	; [C] effect channel 0
ExtraChannel0:	equ 0fdd8h	; [I] another channel block (type 5 path at $0841)
ExtraChannel5:	equ 0fde8h	; [I] channel blocks of the type 3 sounds ($03D0), SSG A
ExtraChannel6:	equ 0fdf8h	; [I] SSG B
ExtraChannel7:	equ 0fe08h	; [I] SSG C
EffectPlaying:	equ 0fe18h	; [C] $FF while an effect plays (sub_0881)
EffectPriority:	equ 0fe19h	; [C] priority of the playing effect: a lower one is refused (sub_0881)
EffectParam:	equ 0fe1ah	; [I] effect header byte +13 (sub_0881); also command 51h
AdpcmBFadeOn:	equ 0fe1dh	; [I] set by the second optional instrument byte path (SeqSetDetune area); AdpcmBFade runs while it is set
AdpcmBFadeStep:	equ 0fe1eh	; [I] step of AdpcmBFade
AdpcmBFadeVolume:	equ 0fe1fh	; [I] volume of AdpcmBFade, written to YM $1B
EngineStack:	equ 0fe20h	; [C] stack pointer saved by TimerIrq; commands 40h, 47h and 55h restore it to leave the channel
BitTestCommand:	equ 0fe22h	; [I] the command of the last CommandBitTest, compared by ClearRepeatIfOwner
CurrentSound:	equ 0fe23h	; [I] the sound PlaySoundCommand / Command2Eyecatcher started; read by PlaySoundA and the ADPCM-A notes
CommandMode:	equ 0fe25h	; [?] set to 3 by Init, written by two routines nothing calls
SongStarting:	equ 0fe28h	; [I] $FF from PlaySoundA, cleared by the stop commands and SeqEnd
SongRunning:	equ 0fe29h	; [I] $FF from PlaySoundA, cleared by the stop commands and SeqEnd; TimerIrq runs the song channels while it is set
Tempo:	equ 0fe2bh	; [I] song header byte +23, also command 33h; applied by sub_28FE
NoNewCommand:	equ 0fe2ch	; [C] $FF once TakeCommand has taken the command; the NMI clears it
TimerTickA:	equ 0fe2dh	; [I] counter of TimerIrq
TimerTickB:	equ 0fe2eh	; [I] counter of TimerIrq, read by ChannelPitch
AdpcmBEffectMode:	equ 0fe2fh	; [I] set while an ADPCM-B sound effect owns the ADPCM-B channel; selects the second set of flags (FA89, FC34)
SoundLock:	equ 0fe30h	; [C] $FF from Init and commands 4 and 5: PlaySound plays nothing until command 7 or 8 clears it (MAME)
EffectLock:	equ 0fe31h	; [C] set by commands 4 and 6, cleared by 7 and 9: effects are refused while it is set
TimerIrqFlag:	equ 0fe32h	; [?] written once by TimerIrq
TimerIrqPhase:	equ 0fe33h	; [I] phase of TimerIrq, tested several times in it
FadeAccumulator:	equ 0fe34h	; [I] fade speed accumulator (FadeTick)
FadeCounter:	equ 0fe35h	; [I] fade step counter, +100 per overflow (FadeTick)
SysFlagFE36:	equ 0fe36h	; [?] written by one system command handler only
SysFlagFE37:	equ 0fe37h	; [?] written by one system command handler only
CurrentChannel:	equ 0fe38h	; [C] the channel number the engine is working on (0-14)
SoundCommand:	equ 0fe39h	; [C] the command being run
EffectCommand:	equ 0fe3ah	; [C] the command number of the effect being started (sub_0881)
SoundCommandType:	equ 0fe3bh	; [C] its CommandTypeTable value
StartSoundParam:	equ 0fe3ch	; [I] sound (and word) given by SeqStartSound, read by AdpcmBChannelNote
SsgSlideMode:	equ 0fe3eh	; [I] selects the end test of SsgSlideStep; set by CommandBitTest and a sequence command
SsgSlideClamped:	equ 0fe3fh	; [C] set to 1 by ClampSsgPeriod when the period reached $70
SpecialEffectKind:	equ 0fe40h	; [C] 3 when the ADPCM-B sound started is SpecialEffect, 4 when the effect started is (StartAdpcmBSound, StartEffect); SsgSilence and the stop paths skip it then
AdpcmHold1:	equ 0fe42h	; [I] AdpcmKeyOff leaves a channel group keyed while it is set
AdpcmHold2:	equ 0fe43h	; [I] the same for the next group
AdpcmHold3:	equ 0fe44h	; [I] the same for the next group
SsgNoiseOn:	equ 0fe45h	; [I] SsgNoteOn: d (the noise flag of the note) kept for the mixer bits
QueueRead:	equ 0fe46h	; [C] next CommandQueue entry to run (0-7)
QueueWrite:	equ 0fe47h	; [C] next free CommandQueue entry (0-7)
CommandQueue:	equ 0fe48h	; [C] 8 entries of 2 bytes: $FF while waiting, then the command
CommandWait:	equ 0fe58h	; [I] set while a command waits for the previous one (loop at $0C3D); the NMI then stores the command straight in SoundCommand
QueueLimit:	equ 0fe5ch	; [I] QueueCheckFull compares QueueWrite with it; set by MainLoop
RandomReplyOn:	equ 0fe65h	; [I] cleared by most system commands; MainLoop sends random replies while it is set
InRamLoop:	equ 0fe66h	; [C] 1 while the Z80 waits in RAM after command 1 (PrepareSwitch)
SoftResetFlag:	equ 0fe68h	; [C] set to 1 by SoftReset before jumping to Reset
ReplyValue:	equ 0fe69h	; [I] random value (ld a,r) sent with bit 7 as the reply after each command
StackTop:	equ 0fffch	; [C] initial stack pointer (Init and the system commands)
RamLoop:	equ 0fffdh	; [C] jp $FFFD, written by PrepareSwitch: the Z80 loops here during a ROM switch

	org 00000h
; Reset [C] di, jp Init
Reset:
	di	; 0000  interrupts off, then the start-up code
	jp Init	; 0001
	defb 000h,000h,000h,000h	; 0004
; RstDelayShort [C] rst 08h: jp DelayShort
RstDelayShort:
	jp DelayShort	; 0008  rst 08h: short wait
	defb 000h,000h,000h,000h,000h	; 000B
; RstDelay [C] rst 10h: jp Delay
RstDelay:
	jp Delay	; 0010  rst 10h: longer wait
	defb 000h	; 0013
; RomChecksum [C] checksum byte: the sum of $0000-$EFFF (this byte included) is $D4 (Command10SelfTest; checked here: $D4)
RomChecksum:
	defb 0d4h,02ch,000h,000h	; 0014
; RstYmWriteA [C] rst 18h: jp YmWriteA
RstYmWriteA:
	jp YmWriteA	; 0018  rst 18h: YM2610 port A write, d = register, e = value
	defb 0c9h,000h,000h,000h,000h	; 001B
; RstYmWriteB [C] rst 20h: jp YmWriteB
RstYmWriteB:
	jp YmWriteB	; 0020  rst 20h: YM2610 port B write
	defb 000h,000h,000h,000h,000h	; 0023
; RstSystemCommand [C] rst 28h: jp SystemCommand
RstSystemCommand:
	jp SystemCommand	; 0028  rst 28h: system command a through SystemCommandTable
	defb 000h,000h,000h,000h,000h,000h,000h,000h,000h,000h,000h,000h,000h	; 002B
; IrqVector [C] mode 1 interrupt (the YM2610 timers, wiki): di, jp TimerIrq
IrqVector:
	di	; 0038  IM 1 interrupt: the YM2610 timer, which runs the sound engine
	jp TimerIrq	; 0039
	defb 000h,000h	; 003C
; VersionText [C] Ver 1.5b by Mr.Pac h Ber.02/01/08 (the signature on the wiki SM1 page)
VersionText:
	defb 056h,065h,072h,020h,031h,02eh,035h,062h,020h,062h,079h,020h,04dh,072h,02eh,050h	; 003E
	defb 061h,063h,020h,068h,020h,042h,065h,072h,02eh,030h,032h,02fh,030h,031h,02fh,030h	; 004E
	defb 038h,000h,000h,000h,000h,000h,000h,000h	; 005E
; Nmi [C] command from the 68k: 1, 3 and $10 are handled at once (NmiPrepareSwitch, NmiReset, NmiCommand10); 0 is ignored; any other is queued in CommandQueue (or put straight in SoundCommand while CommandWait is set); then the reply (ReplyValue with bit 7) and the port $00 clear. MAME: every command of the hardware test and the boot
Nmi:
	push af	; 0066  NMI: a command byte from the 68000
	push bc	; 0067
	push de	; 0068
	push hl	; 0069
	in a,(PORT_SOUND_CODE)	; 006A  read the command (port 00h)
	ld b,a	; 006C
	cp 001h	; 006D  1: prepare for a ROM switch, handled at once
	jp z,NmiPrepareSwitch	; 006F
	cp 003h	; 0072  3: reset, handled at once
	jp z,NmiReset	; 0074
	cp 010h	; 0077  10h: self test, handled at once
	jp z,NmiCommand10	; 0079
	or a	; 007C  0: nothing
	jp z,NmiExit	; 007D
	ld a,(CommandWait)	; 0080  a command is being waited for (CommandWait): take it directly
	or a	; 0083
	jr nz,loc_00A8	; 0084
	ld a,080h	; 0086  otherwise queue it
	call QueueCheckFull	; 0088
	ld a,(QueueWrite)	; 008B  8 entries of 2 bytes: a flag ($FF) and the command
	and 007h	; 008E
	ld e,a	; 0090
	ld d,000h	; 0091
	ld hl,CommandQueue	; 0093
	add hl,de	; 0096
	add hl,de	; 0097
	ld (hl),0ffh	; 0098
	inc hl	; 009A
	ld (hl),b	; 009B
	inc a	; 009C  next write position, 0-7
	and 007h	; 009D
	ld (QueueWrite),a	; 009F
	xor a	; 00A2
	ld (NoNewCommand),a	; 00A3
	jr loc_00B0	; 00A6
loc_00A8:
	ld a,b	; 00A8  the command straight into SoundCommand
	ld (SoundCommand),a	; 00A9
	xor a	; 00AC
	ld (NoNewCommand),a	; 00AD
loc_00B0:
	ld a,(ReplyValue)	; 00B0  reply: a byte with bit 7 set
	or 080h	; 00B3
	out (PORT_REPLY),a	; 00B5
	out (PORT_SOUND_CODE),a	; 00B7  acknowledge the command latch
; NmiExit [C] restores the registers and retn
NmiExit:
	pop hl	; 00B9
	pop de	; 00BA
	pop bc	; 00BB
	pop af	; 00BC
	retn	; 00BD  return from NMI
	defs 00011h,000h	; 00BF
; Init [C] stack $FFFC, interrupt mode 1, clears the 2 KB of RAM, sets SoundLock, writes 1 to port $C0 and YM2610 registers $27, $10, $1C, enables the NMI (port $08) and enters MainLoop. Run at every reset (MAME)
Init:
	ld sp,StackTop	; 00D0  stack at the top of RAM
	im 1	; 00D3  interrupt mode 1 (rst 38h)
	xor a	; 00D5
	ld (InRamLoop),a	; 00D6
	ld (SsgPeriodA),a	; 00D9  clear the 2 KB of work RAM from SsgPeriodA
	ld hl,SsgPeriodA	; 00DC
	ld de,SsgPeriodA+1	; 00DF
	ld bc,007ffh	; 00E2
	ldir	; 00E5
	ld a,0ffh	; 00E7  no command yet, music and effects locked until command 7
	ld (NoNewCommand),a	; 00E9
	ld (SoundLock),a	; 00EC
	ld (EffectLock),a	; 00EF
	ld a,003h	; 00F2  command mode 3
	ld (CommandMode),a	; 00F4
	call FmKeyOffAll	; 00F7  everything silent
	call AdpcmKeyOff	; 00FA
	call SsgSilence	; 00FD
	ld a,001h	; 0100  port C0h = 1
	out (PORT_C0),a	; 0102
	ld de,02730h	; 0104  YM2610 register 27h = 30h: timers reset
	call YmWriteA	; 0107
	ld de,01001h	; 010A  register 10h = 01h
	call YmWriteA	; 010D
	ld de,01c00h	; 0110  register 1Ch = 00h
	call YmWriteA	; 0113
	xor a	; 0116
	ld (RandomReplyOn),a	; 0117
	ld (PitchEnvelopeOn),a	; 011A
	ld (AdpcmBEffectMode),a	; 011D
	ld (SongRunning),a	; 0120
	ld (SongStarting),a	; 0123
	ld a,003h	; 0126  timer A from TimerATable entry 3
	call SetTimerA	; 0128
	ld a,00ah	; 012B
	ld (AdpcmBFadeStep),a	; 012D
	call SilenceAll	; 0130  every channel off
	out (PORT_NMI_ENABLE),a	; 0133  enable the NMI: commands may come in
; MainLoop [C] takes the next queued command (CommandQueue, QueueRead) and runs it (TakeCommand); while RandomReplyOn is set, sends a random reply (ld a,r | $80) to port $0C
MainLoop:
	xor a	; 0135  main loop: no command awaited, not in the RAM loop
	ld (CommandWait),a	; 0136
	ld (InRamLoop),a	; 0139
	ei	; 013C  interrupts on (the timer runs the engine)
	ld a,(QueueRead)	; 013D  the next queue entry
	and 007h	; 0140
	ld (QueueLimit),a	; 0142
	ld e,a	; 0145  2 bytes per entry
	ld d,000h	; 0146
	ld hl,CommandQueue	; 0148
	add hl,de	; 014B
	add hl,de	; 014C
	inc a	; 014D
	ld (QueueRead),a	; 014E
	ld a,(hl)	; 0151  flag set: a command is waiting
	or a	; 0152
	call nz,TakeCommand	; 0153
	ei	; 0156
	ld a,(RandomReplyOn)	; 0157  random reply on: a new random reply byte each pass
	or a	; 015A
	jr z,MainLoop	; 015B
	ld a,r	; 015D  the refresh register as the random value
	ld (ReplyValue),a	; 015F
	or 080h	; 0162
	out (PORT_REPLY),a	; 0164  reply with bit 7 set
	jp MainLoop	; 0166
; TakeCommand [C] marks the queue entry free, SoundCommand = the command, then DispatchCommand
TakeCommand:
	ld a,0ffh	; 0169  take the command out of the queue
	ld (NoNewCommand),a	; 016B
	ld (hl),000h	; 016E
	inc hl	; 0170
	ld a,(hl)	; 0171  the command byte
	ld (SoundCommand),a	; 0172
; DispatchCommand [C] CommandTypeTable[SoundCommand]: 1 system command (rst 28h), 2 a sound or tune (PlaySoundCommand), 5 the coin sound (CoinSound); types 3 and 4 ($01C4, $048E) are handled but no command has them; 0 ignored
DispatchCommand:
	ld e,a	; 0175  look up its type in CommandTypeTable
	ld d,000h	; 0176
	ld hl,CommandTypeTable	; 0178
	add hl,de	; 017B
	ld a,(hl)	; 017C
	ld (SoundCommandType),a	; 017D
	ld a,(SoundCommandType)	; 0180
	or a	; 0183  type 0: ignored
	ret z	; 0184
	cp 001h	; 0185  1: system command
	jp z,SystemCommand	; 0187
	cp 002h	; 018A  2: sound or tune
	jp z,PlaySoundCommand	; 018C
	cp 003h	; 018F  3: ADPCM-A sound (no command of this ROM)
	jp z,loc_01C4	; 0191
	cp 004h	; 0194  4: ADPCM-B sound (no command of this ROM)
	jp z,loc_048E	; 0196
	cp 005h	; 0199  5: coin sound
	jp z,CoinSound	; 019B
	xor a	; 019E  anything else: dropped
	ld (SoundCommandType),a	; 019F
	ld (SoundCommand),a	; 01A2
	ret	; 01A5
; PlaySoundCommand [C] command type 2 ($5C-$5F): jp PlaySound with the command
PlaySoundCommand:
	xor a	; 01A6  sound from the start
	ld (CurrentSound),a	; 01A7
	jp PlaySound	; 01AA
; ClearCommandQueue [C] clears QueueRead / QueueWrite and the 16 bytes of CommandQueue
ClearCommandQueue:
	push hl	; 01AD  empty the queue: both positions 0
	ld hl,QueueWrite	; 01AE
	ld (hl),000h	; 01B1
	ld hl,QueueRead	; 01B3
	ld (hl),000h	; 01B6
	ld hl,CommandQueue	; 01B8
	ld b,010h	; 01BB  16 bytes
loc_01BD:
	ld (hl),000h	; 01BD
	inc hl	; 01BF
	djnz loc_01BD	; 01C0
	pop hl	; 01C2
	ret	; 01C3
loc_01C4:
	di	; 01C4
	ld a,(SoundCommand)	; 01C5
	ld (EffectCommand),a	; 01C8
	call LookupTable5314	; 01CB
; StartAdpcmASound [I] command type 3 ($01C4): an ADPCM-A sample sound from AdpcmASampleTable on one of three voices (AdpcmAFindVoice), refused while EffectLock is set unless it is SpecialEffect; no command of this ROM has type 3
StartAdpcmASound:
	ld e,a	; 01CE
	ex af,af'	; 01CF
	ld a,e	; 01D0
	ex af,af'	; 01D1
	push bc	; 01D2
	ld a,(SpecialEffect)	; 01D3
	ld b,a	; 01D6
	ld a,(EffectCommand)	; 01D7
	cp b	; 01DA
	pop bc	; 01DB
	jr z,loc_01E3	; 01DC
	ld a,(EffectLock)	; 01DE
	or a	; 01E1
	ret nz	; 01E2
loc_01E3:
	ld a,e	; 01E3
	cp 0c0h	; 01E4
	jp nc,loc_03AA	; 01E6
	call AdpcmASample	; 01E9
	call AdpcmAFindVoice	; 01EC
	ret c	; 01EF
	sub 008h	; 01F0
	ld c,a	; 01F2
	ld b,008h	; 01F3
	add a,b	; 01F5
	ld d,a	; 01F6
	ld e,(ix+10)	; 01F7
	call YmWriteB	; 01FA
	ld a,c	; 01FD
; AdpcmAKeyOn [I] ADPCM-A note on: key (YM port B $00), flag reset (YM $1C), the sample's addresses and its repeat record (AdpcmARepeatRecord)
AdpcmAKeyOn:
	ld hl,ChannelBitTable	; 01FE
	ld e,a	; 0201
	ld d,000h	; 0202
	add hl,de	; 0204
	ld e,(hl)	; 0205
	ld b,e	; 0206
	ex af,af'	; 0207
	ld a,080h	; 0208
	or e	; 020A
	ld d,000h	; 020B
	ld e,a	; 020D
	call YmWriteB	; 020E
	ex af,af'	; 0211
	ld d,01ch	; 0212
	ld e,b	; 0214
	call YmWriteA	; 0215
	ld de,01c00h	; 0218
